export function getArticleBySlug(slug: string): Article | undefined {
  return articles.find((art) => art.slug === slug);
}

export function getArticleTitle(art: Article, lang: Language): string {
  if (lang === 'ur') return art.titleUrdu;
  if (lang === 'en') return art.titleEnglish;
  return art.titleRoman;
}

export function getArticleSummary(art: Article, lang: Language): string {
  if (lang === 'ur') return art.summaryUrdu;
  if (lang === 'en') return art.summaryEnglish;
  return art.summaryRoman;
}

export function getArticleAuthor(art: Article, lang: Language): string {
  if (lang === 'ur') return art.authorUrdu;
  if (lang === 'en') return art.authorEnglish;
  return art.author;
}

export function getArticleReadTime(art: Article, lang: Language): string {
  if (lang === 'ur') return art.readTimeUrdu;
  if (lang === 'en') return art.readTimeEnglish;
  return art.readTime;
}
